<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class OperationalOversightService
{
 use DeliveryOperations;
 public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
 public function equipment(array $in):array {$this->fields($in,['site_id']);$site=$this->access->requireSite($in['site_id']??null);$rows=$this->db->fetchAll('SELECT s.*,e.asset_code,e.equipment_name FROM equipment_check_schedules s JOIN equipment_items e ON e.company_id=s.company_id AND e.equipment_id=s.equipment_id WHERE s.company_id=:company AND s.site_id=:site ORDER BY next_due_at LIMIT 300',['company'=>$this->company(),'site'=>$site['site_id']]);foreach($rows as&$r){$r['checklist']=json_decode($r['checklist_json'],true);unset($r['checklist_json']);$r['results']=$this->db->fetchAll('SELECT result_id,checks_json,passed,notes,maintenance_ticket_id,checked_by_user_id,checked_at FROM equipment_check_results WHERE company_id=:company AND schedule_id=:id ORDER BY result_id DESC LIMIT 100',['company'=>$this->company(),'id'=>$r['schedule_id']]);}return $rows;}
 public function schedule(array $in):array {return $this->atomic(function()use($in){$this->fields($in,['site_id','equipment_id','checklist','interval_days','assignee_user_id','next_due_at']);$site=$this->access->requireSite($in['site_id']??null);$e=$this->row('equipment_items','equipment_id',$in['equipment_id']??null);$u=$this->operator($in['assignee_user_id']??null,$site['site_id'],'equipment_checks.manage');$checks=$this->strings($in['checklist']??null,20);$at=$this->at($in['next_due_at']??null);if($this->db->fetch('SELECT schedule_id FROM equipment_check_schedules WHERE company_id=:company AND equipment_id=:id',['company'=>$this->company(),'id'=>$e['equipment_id']]))throw HttpException::conflict('Equipment already has a check schedule.');$this->db->execute('INSERT INTO equipment_check_schedules(company_id,site_id,equipment_id,checklist_json,interval_days,assignee_user_id,next_due_at) VALUES(:company,:site,:equipment,:checks,:days,:assignee,:due)',['company'=>$this->company(),'site'=>$site['site_id'],'equipment'=>$e['equipment_id'],'checks'=>json_encode($checks,JSON_THROW_ON_ERROR),'days'=>$this->number($in['interval_days']??null,1,365),'assignee'=>$u['user_id'],'due'=>$at]);return $this->created('equipment_check_schedule');});}
 public function reschedule(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','assignee_user_id','next_due_at','interval_days','active','notes']);$r=$this->row('equipment_check_schedules','schedule_id',$id);$this->access->requireSite($r['site_id']);$this->revision($r,$in);$u=$this->operator($in['assignee_user_id']??null,$r['site_id'],'equipment_checks.manage');if(!is_bool($in['active']??null))throw HttpException::unprocessable('Use an explicit active flag.');$this->db->execute('UPDATE equipment_check_schedules SET assignee_user_id=:user,next_due_at=:due,interval_days=:days,active=:active,revision=revision+1 WHERE company_id=:company AND schedule_id=:id',['user'=>$u['user_id'],'due'=>$this->at($in['next_due_at']??null),'days'=>$this->number($in['interval_days']??null,1,365),'active'=>(int)$in['active'],'company'=>$this->company(),'id'=>$id]);$this->history('equipment_schedule',$id,'RESCHEDULED','Inspector #'.$r['assignee_user_id'].' to #'.$u['user_id'].': '.$this->text($in['notes']??null,1000));return ['saved'=>true];});}
 public function inspect(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','operation_uuid','checks','notes']);$s=$this->row('equipment_check_schedules','schedule_id',$id);$this->access->requireSite($s['site_id']);$uuid=$in['operation_uuid']??null;if(!is_string($uuid)||!preg_match('/^[a-f0-9-]{36}$/Di',$uuid))throw HttpException::unprocessable('Use a stable UUID.');$hash=hash('sha256',json_encode([$id,$this->actor(),$in],JSON_THROW_ON_ERROR));$old=$this->db->fetch('SELECT result_id,request_hash,maintenance_ticket_id FROM equipment_check_results WHERE company_id=:company AND operation_uuid=:uuid',['company'=>$this->company(),'uuid'=>$uuid]);if($old){if(!hash_equals($old['request_hash'],$hash))throw HttpException::conflict('Inspection retry changed.');return ['id'=>(string)$old['result_id'],'maintenance_ticket_id'=>$old['maintenance_ticket_id']];}$this->revision($s,$in);if(!$s['active']||(string)$s['assignee_user_id']!==$this->actor())throw HttpException::forbidden('The assigned inspector must record this check.');$checks=$in['checks']??null;$list=json_decode($s['checklist_json'],true);if(!is_array($checks)||!array_is_list($checks)||count($checks)!==count($list))throw HttpException::unprocessable('Answer every scheduled check.');foreach($checks as$v)if(!is_bool($v))throw HttpException::unprocessable('Use explicit yes/no check results.');$passed=!in_array(false,$checks,true);$notes=$this->text($in['notes']??null,2000);$ticket=null;$now=gmdate('Y-m-d H:i:s');$open=$this->db->fetch("SELECT ticket_id FROM maintenance_tickets WHERE company_id=:company AND equipment_id=:equipment AND state NOT IN ('VERIFIED','CANCELLED')",['company'=>$this->company(),'equipment'=>$s['equipment_id']]);if($passed&&$open)throw HttpException::conflict('Verify the outstanding maintenance defect before recording a passed inspection.');if(!$passed){if($open)$ticket=$open['ticket_id'];else{$this->db->execute("INSERT INTO maintenance_tickets(company_id,site_id,equipment_id,asset_type,title,description,priority,assignee_user_id,state,created_by_user_id,created_at,updated_at) VALUES(:company,:site,:equipment,'EQUIPMENT',:title,:description,'HIGH',:assignee,'OPEN',:actor,:now,:updated)",['company'=>$this->company(),'site'=>$s['site_id'],'equipment'=>$s['equipment_id'],'title'=>'Failed scheduled equipment check','description'=>$notes,'assignee'=>$s['assignee_user_id'],'actor'=>$this->actor(),'now'=>$now,'updated'=>$now]);$ticket=$this->db->connection()->lastInsertId();$this->db->execute("INSERT INTO maintenance_history(company_id,ticket_id,state,notes,actor_user_id,occurred_at) VALUES(:company,:ticket,'OPEN',:notes,:actor,:now)",['company'=>$this->company(),'ticket'=>$ticket,'notes'=>$notes,'actor'=>$this->actor(),'now'=>$now]);}}$this->db->execute('INSERT INTO equipment_check_results(company_id,schedule_id,operation_uuid,request_hash,checks_json,passed,notes,maintenance_ticket_id,checked_by_user_id,checked_at) VALUES(:company,:schedule,:uuid,:hash,:checks,:passed,:notes,:ticket,:actor,:now)',['company'=>$this->company(),'schedule'=>$id,'uuid'=>$uuid,'hash'=>$hash,'checks'=>json_encode($checks,JSON_THROW_ON_ERROR),'passed'=>(int)$passed,'notes'=>$notes,'ticket'=>$ticket,'actor'=>$this->actor(),'now'=>$now]);$result=$this->created('equipment_check');$this->db->execute('UPDATE equipment_check_schedules SET next_due_at=:due,revision=revision+1 WHERE company_id=:company AND schedule_id=:id',['due'=>gmdate('Y-m-d H:i:s',time()+(int)$s['interval_days']*86400),'company'=>$this->company(),'id'=>$id]);return $result+['maintenance_ticket_id'=>$ticket,'passed'=>$passed];});}
 public function snapshot(mixed $site):array {$s=$this->access->requireSite($site);$p=['company'=>$this->company(),'site'=>$s['site_id']];$incidents=$this->db->fetchAll("SELECT incident_id,incident_number,severity,status FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND status IN ('OPEN','INVESTIGATING') ORDER BY incident_id LIMIT 501",$p);$patrols=$this->db->fetchAll("SELECT p.patrol_session_id,p.status,p.started_at FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.status='IN_PROGRESS' ORDER BY p.patrol_session_id LIMIT 501",$p);$missed=$this->db->fetchAll("SELECT w.patrol_schedule_id,w.starts_at,w.ends_at FROM patrol_schedule_windows w JOIN patrol_routes r ON r.company_id=w.company_id AND r.patrol_route_id=w.patrol_route_id WHERE w.company_id=:company AND r.site_id=:site AND w.cancelled_at IS NULL AND w.ends_at<:now AND NOT EXISTS(SELECT 1 FROM patrol_sessions p WHERE p.company_id=w.company_id AND p.patrol_route_id=w.patrol_route_id AND p.deleted_at IS NULL AND p.status='COMPLETED' AND (w.shift_assignment_id IS NULL OR p.shift_assignment_id=w.shift_assignment_id) AND p.started_at>=w.starts_at AND p.started_at<=w.ends_at) ORDER BY w.ends_at DESC LIMIT 501",$p+['now'=>gmdate('Y-m-d H:i:s')]);$keys=$this->db->fetchAll("SELECT l.loan_id,a.asset_code,l.employee_id,l.state,l.due_at FROM custody_loans l JOIN custody_assets a ON a.company_id=l.company_id AND a.asset_id=l.asset_id WHERE l.company_id=:company AND a.site_id=:site AND l.state IN ('PENDING_ACCEPTANCE','ISSUED','RETURN_PENDING','LOST') ORDER BY l.loan_id LIMIT 501",$p);$equipment=$this->db->fetchAll('SELECT handover_id,equipment_id,employee_id,issued_at FROM equipment_handovers WHERE company_id=:company AND site_id=:site AND returned_at IS NULL ORDER BY handover_id LIMIT 501',$p);foreach([$incidents,$patrols,$missed,$keys,$equipment]as$r)if(count($r)>500)throw HttpException::conflict('Handover exceeds 500 records in a category; review backlog first.');return ['generated_at'=>gmdate('Y-m-d H:i:s'),'site_id'=>$s['site_id'],'unresolved_incidents'=>$incidents,'active_patrols'=>$patrols,'missed_patrol_windows'=>$missed,'outstanding_keys'=>$keys,'outstanding_equipment'=>$equipment];}
 public function handovers(array $in):array {$this->fields($in,['site_id']);$site=$this->access->requireSite($in['site_id']??null);$rows=$this->db->fetchAll('SELECT * FROM control_room_handovers WHERE company_id=:company AND site_id=:site ORDER BY handover_id DESC LIMIT 200',['company'=>$this->company(),'site'=>$site['site_id']]);foreach($rows as&$r){$r['snapshot']=json_decode($r['snapshot_json'],true);unset($r['snapshot_json']);}return ['current'=>$this->snapshot($site['site_id']),'handovers'=>$rows];}
 public function handover(array $in):array {return $this->atomic(function()use($in){$this->fields($in,['site_id','incoming_user_id','notes']);$site=$this->access->requireSite($in['site_id']??null);$u=$this->operator($in['incoming_user_id']??null,$site['site_id'],'control_handover.manage');if((string)$u['user_id']===$this->actor())throw HttpException::unprocessable('Choose a different incoming supervisor.');$snapshot=json_encode($this->snapshot($site['site_id']),JSON_THROW_ON_ERROR);$this->db->execute('INSERT INTO control_room_handovers(company_id,site_id,outgoing_user_id,incoming_user_id,snapshot_json,snapshot_hash,notes,created_at) VALUES(:company,:site,:outgoing,:incoming,:snapshot,:hash,:notes,:now)',['company'=>$this->company(),'site'=>$site['site_id'],'outgoing'=>$this->actor(),'incoming'=>$u['user_id'],'snapshot'=>$snapshot,'hash'=>hash('sha256',$snapshot),'notes'=>$this->text($in['notes']??null,4000),'now'=>gmdate('Y-m-d H:i:s')]);return $this->created('control_handover');});}
 public function acceptHandover(string $id,array $in):array {return $this->atomic(function()use($id,$in){$this->fields($in,['expected_revision','expected_hash','notes']);$r=$this->row('control_room_handovers','handover_id',$id);$this->access->requireSite($r['site_id']);$this->revision($r,$in);if((string)$r['incoming_user_id']!==$this->actor())throw HttpException::forbidden('Only the named incoming supervisor can accept.');if($r['state']!=='PENDING'||!is_string($in['expected_hash']??null)||!hash_equals($r['snapshot_hash'],$in['expected_hash'])||!hash_equals($r['snapshot_hash'],hash('sha256',$r['snapshot_json'])))throw HttpException::conflict('Handover changed.');$notes=$this->text($in['notes']??null,2000);$this->db->execute("UPDATE control_room_handovers SET state='ACCEPTED',revision=revision+1,accepted_at=:now,acceptance_notes=:notes WHERE company_id=:company AND handover_id=:id",['now'=>gmdate('Y-m-d H:i:s'),'notes'=>$notes,'company'=>$this->company(),'id'=>$id]);$this->history('control_handover',$id,'ACCEPTED',$notes);return ['accepted'=>true,'note'=>'Receipt of the recorded snapshot; compare current operations for later changes.'];});}
 public function analytics(array $in):array {
 $this->fields($in,['date_from','date_to','weekly_threshold_minutes']);$from=$this->day($in['date_from']??null);$to=$this->day($in['date_to']??null);if($to<$from||strtotime($to.' UTC')-strtotime($from.' UTC')>30*86400)throw HttpException::unprocessable('Choose at most 31 inclusive UTC days.');$threshold=$this->number($in['weekly_threshold_minutes']??2880,60,10080)*60;$end=gmdate('Y-m-d',strtotime($to.' UTC')+86400).' 00:00:00';$p=['company'=>$this->company(),'start'=>$from.' 00:00:00','end'=>$end];$sites=$this->access->sites();if(count($sites)>=500)throw HttpException::conflict('Analytics is limited to fewer than 500 sites.');$out=[];foreach($sites as$s){$id=(string)$s['site_id'];$v=$p+['site'=>$id];$patrol=$this->db->fetchAll('SELECT p.status FROM patrol_sessions p JOIN patrol_routes r ON r.company_id=p.company_id AND r.patrol_route_id=p.patrol_route_id WHERE p.company_id=:company AND r.site_id=:site AND p.deleted_at IS NULL AND p.started_at>=:start AND p.started_at<:end',$v);$responses=$this->db->fetchAll('SELECT d.created_at,d.arrived_at FROM dispatch_jobs d JOIN incidents i ON i.company_id=d.company_id AND i.incident_id=d.incident_id WHERE d.company_id=:company AND i.site_id=:site AND i.deleted_at IS NULL AND d.created_at>=:start AND d.created_at<:end',$v);$times=[];foreach($responses as$r)if($r['arrived_at']&&$r['arrived_at']>=$r['created_at'])$times[]=strtotime($r['arrived_at'].' UTC')-strtotime($r['created_at'].' UTC');$out[$id]=['site_id'=>$s['site_id'],'site_name'=>$s['site_name'],'recorded_patrol_sessions'=>count($patrol),'completed_patrol_sessions'=>count(array_filter($patrol,fn($r)=>$r['status']==='COMPLETED')),'arrivals_recorded'=>count($times),'mean_dispatch_to_arrival_seconds'=>$times?(int)round(array_sum($times)/count($times)):null,'approved_work_seconds'=>0,'estimated_overtime_seconds'=>0,'recurring_incident_types'=>$this->db->fetchAll('SELECT incident_type,COUNT(*) AS total FROM incidents WHERE company_id=:company AND site_id=:site AND deleted_at IS NULL AND occurred_at>=:start AND occurred_at<:end GROUP BY incident_type ORDER BY total DESC LIMIT 20',$v)];}
 $weekStart=(new \DateTimeImmutable($from.' UTC'))->modify('monday this week')->format('Y-m-d');$weekEnd=(new \DateTimeImmutable($to.' UTC'))->modify('monday next week')->format('Y-m-d');$rows=$this->db->fetchAll('SELECT a.attendance_id,a.employee_id,a.site_id,a.shift_date,a.clock_in_at,a.clock_out_at,p.record_hash FROM attendance a LEFT JOIN attendance_approvals p ON p.company_id=a.company_id AND p.attendance_id=a.attendance_id WHERE a.company_id=:company AND a.deleted_at IS NULL AND a.shift_date>=:start AND a.shift_date<:end ORDER BY a.employee_id,a.clock_in_at,a.attendance_id LIMIT 10001',['company'=>$this->company(),'start'=>$weekStart,'end'=>$weekEnd]);if(count($rows)>10000)throw HttpException::conflict('Attendance range exceeds the analytics limit.');$totals=[];$lastEnd=[];$excluded=0;foreach($rows as$r){$expected=$r['record_hash'];unset($r['record_hash']);$a=strtotime(($r['clock_in_at']??'').' UTC');$b=strtotime(($r['clock_out_at']??'').' UTC');if(!$r['clock_in_at']||!$r['clock_out_at']||!$expected||!hash_equals($expected,FieldOperationsService::attendanceHash($r))||!$a||!$b||$b<=$a||$b-$a>48*3600||$a<($lastEnd[$r['employee_id']]??0)){$excluded++;continue;}$lastEnd[$r['employee_id']]=$b;for($cursor=$a;$cursor<$b;){$boundary=(new \DateTimeImmutable('@'.$cursor))->setTimezone(new \DateTimeZone('UTC'))->modify('monday next week')->setTime(0,0)->getTimestamp();$stop=min($b,$boundary);$week=(new \DateTimeImmutable('@'.$cursor))->setTimezone(new \DateTimeZone('UTC'))->modify('monday this week')->format('Y-m-d');$key=$r['employee_id'].':'.$week;$before=$totals[$key]??0;$duration=$stop-$cursor;$totals[$key]=$before+$duration;$visibleStart=max($cursor,strtotime($p['start'].' UTC'));$visibleEnd=min($stop,strtotime($end.' UTC'));$id=(string)$r['site_id'];if(isset($out[$id])&&$visibleEnd>$visibleStart){$out[$id]['approved_work_seconds']+=$visibleEnd-$visibleStart;$overtimeStart=$cursor+max(0,$threshold-$before);$out[$id]['estimated_overtime_seconds']+=max(0,$visibleEnd-max($visibleStart,$overtimeStart));}$cursor=$stop;}}
 return ['date_from'=>$from,'date_to'=>$to,'timezone'=>'UTC','weekly_threshold_minutes'=>intdiv($threshold,60),'excluded_unapproved_stale_invalid_or_overlapping_attendance'=>$excluded,'sites'=>array_values($out),'note'=>'Overtime is an estimate above your chosen UTC-week threshold on current approved clock durations, without breaks, pay rules or statutory calculations. Patrol completion counts recorded sessions, not unrecorded required patrols. Missing arrivals remain unknown.'];
 }
